ZUORDNUNG = {
    # alte Funktion: (Kürzel, Bezeichnung, unterrichtend)
    "lehrkraft": ("LK", "Lehrkräfte", True),
    "leitung": ("SL", "Schulleitung", True),
    "verwaltung": ("VERW", "Verwaltung / Sekretariat", False),
    "paedagogik": ("NACHM", "Nachmittagsbereich / Coaches", False),
    "technik": ("FAC", "Facility Management / Haustechnik", False),
}


def funktion_zu_bereich(apps, schema_editor):
    Personalprofil = apps.get_model("stammdaten", "Personalprofil")
    Personalbereich = apps.get_model("stammdaten", "Personalbereich")
    for p in Personalprofil.objects.all():
        eintrag = ZUORDNUNG.get(p.funktion)
        if eintrag:
            k, name, unterrichtet = eintrag
            bereich, _ = Personalbereich.objects.get_or_create(kuerzel=k, defaults={"name": name, "unterrichtet": unterrichtet})
            p.bereich = bereich
            p.save(update_fields=["bereich"])


